import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from "expo-audio";
import * as SecureStore from "expo-secure-store";
import { useSyncExternalStore } from "react";

// Sound router: the ONE place that decides what each moment sounds like. Screens call play("coin") etc.
// Every name points at a file in mobile/assets/sounds/. tone-*.wav are generated by
// app/scripts/gen-sounds.mjs (edit + re-run it to tweak a tone; it only writes tone-* files).
// Use a downloaded sound instead: put it in mobile/assets/sounds/ (mp3, wav or m4a; keep it under ~1.5s)
// and change that name's line below, e.g.  coin: require("../../assets/sounds/coin-drop.mp3"),
// then rebuild the app (sounds are bundled). The website has the same map in app/src/lib/sound.ts.
const ROUTES = {
  sent: require("../../assets/sounds/tone-sent.wav"), // payment delivered (right after Send)
  received: require("../../assets/sounds/tone-received.wav"), // money came in (live while the app is open, or a collected link)
  coin: require("../../assets/sounds/tone-coin.wav"), // any other money action done: chore paid, pot add, allowance collect, circle pay…
  success: require("../../assets/sounds/tone-success.wav"), // done screens: link ready, gift wrapped, bill split…
  cashout: require("../../assets/sounds/tone-cashout.wav"), // cash-out on its way
  scan: require("../../assets/sounds/tone-scan.wav"), // QR code read
  error: require("../../assets/sounds/tone-error.wav"), // any red error message
  celebrate: require("../../assets/sounds/tone-celebrate.wav"), // big wins with confetti: pot goal reached, jar filled
  gift: require("../../assets/sounds/tone-gift.wav"), // gift lid pops open
} as const;

export type Sound = keyof typeof ROUTES;

const KEY = "kin.sound";
const players = new Map<Sound, AudioPlayer>();
const last = new Map<Sound, number>();
let moded = false;

const isOn = () => SecureStore.getItem(KEY) !== "0";

/** Play a moment's sound. Silent if muted or the phone is on silent; never stops the user's music. */
export function play(s: Sound) {
  const now = Date.now();
  if (!isOn() || now - (last.get(s) ?? 0) < 1500) return; // one moment, one sound (live + screen)
  last.set(s, now);
  try {
    if (!moded) {
      moded = true;
      void setAudioModeAsync({ playsInSilentMode: false, interruptionMode: "mixWithOthers" }).catch(() => {});
    }
    let p = players.get(s);
    if (!p) players.set(s, (p = createAudioPlayer(ROUTES[s])));
    void p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // no audio: stay silent
  }
}

const listeners = new Set<() => void>();
export function setSoundOn(on: boolean) {
  SecureStore.setItem(KEY, on ? "1" : "0");
  listeners.forEach((l) => l());
}
export const useSoundOn = () => useSyncExternalStore((l) => (listeners.add(l), () => listeners.delete(l)), isOn);
